<span class="line"><span style="color:#E5C07B;">channel</span><span style="color:#ABB2BF;">.</span><span style="color:#61AFEF;">BasicPublish</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&quot;doc.headers&quot;</span><span style="color:#ABB2BF;">, </span><span style="color:#E5C07B;">routingKey</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">&quot;&quot;</span><span style="color:#ABB2BF;">, </span><span style="color:#E06C75;">properties</span><span style="color:#ABB2BF;">, </span><span style="color:#E06C75;">body</span><span style="color:#ABB2BF;">);</span></span>
